import{_ as m,a0 as u,w as n,s as l,ao as p,I as a,x as e,a1 as i,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"如何輕鬆備份及恢復Firefox和Chromium的瀏覽器數據 | LCTT x X-CMD","titleTemplate":false,"description":"如何輕鬆備份及恢復Firefox和Chromium的瀏覽器數據 | LCTT (201309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何輕鬆備份及恢復Firefox和Chromium的瀏覽器數據 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何輕鬆備份及恢復Firefox和Chromium的瀏覽器數據 | LCTT (201309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201309/How to easily backup and reuse data of Firefox and Chromium","title":"如何輕鬆備份及恢復Firefox和Chromium的瀏覽器數據","tag":"201309","desc":""},"relativePath":"201309/How to easily backup and reuse data of Firefox and Chromium.md","filePath":"[post].md"}'),d={name:"201309/How to easily backup and reuse data of Firefox and Chromium.md"};function s(f,o,c,h,C,x){const t=u("Link");return n(),l("div",null,[o[11]||(o[11]=p('<h1 id="如何輕鬆備份及恢復firefox和chromium的瀏覽器數據" tabindex="-1">如何輕鬆備份及恢復Firefox和Chromium的瀏覽器數據 <a class="header-anchor" href="#如何輕鬆備份及恢復firefox和chromium的瀏覽器數據" aria-label="Permalink to “如何輕鬆備份及恢復Firefox和Chromium的瀏覽器數據”">​</a></h1><p>網絡及網絡中的網站、音樂、視頻、圖片、文件和書籍等內容在用户的IT生活中扮演着一個至關重要的角色。</p><p>在Ubuntu系統中，用户可以很輕鬆地安裝開源的Chromium (apt://chromium-browser)瀏覽器，它與Ubuntu所帶的默認瀏覽器Firefox一起，為用户提供了一種非常可靠的方式來訪問網絡上的內容。</p><p>然而很多情況下，用户會遇到不得不移動Firefox和Chromium產生的數據的情況，例如為了能在其它的Ubuntu設備或其它的電腦（放在其它地方而沒有放在家裏的電腦）上使用這些數據，或者為了在出現意外情況時（硬盤損壞、電腦丟失等）保護數據。</p><p>有幾種基於遠程同步的備份服務及工具，下面介紹一種方法，它可以提供快捷、可靠並且以隨時可存取的方式來即時地（再）使用Firefox和Chromium的數據（這些數據包括網站歷史記錄、密碼、下載歷史、書籤等基本上所有你使用Firefox和Chromium時產生的數據）。</p><p>這個方法是（在U盤裏存儲數據）：</p><ul><li><p>跳轉到home文件夾下，然後按“Ctrl+H”鍵，顯示出隱藏的文件夾。</p></li><li><p>將<code>.mozilla</code>文件夾複製到U盤中。</p></li></ul><p><img src="http://iloveubuntu.net/pictures_me/mozilla%20wed%20data%20backup.png" alt=""></p><ul><li>將<code>.config</code>文件夾中的<code>chromium</code>文件夾複製到U盤。</li></ul><p><img src="http://iloveubuntu.net/pictures_me/chromium%20web%20data%20backup.png" alt=""></p><p>現在你的U盤中就有<code>.mozilla</code>和<code>chromium</code>這兩個文件夾了。</p><p>從U盤中將<code>.mozilla</code>和<code>chromium</code>這兩個文件夾複製到新的（或舊的）Ubuntu設備中的相應位置（<code>.mozilla</code>在home目錄下，<code>chromium</code> 在 <code>.config</code>目錄下,——刪除舊的將要被替換的<code>.mozilla</code> 和<code>chromium</code>文件夾——）打開Firefox和Chromium，用户就可以使用他們所有的網絡數據了，至此，你就可以擺脱那些同步服務，高級複雜的方法和潛在的不可用性等問題了。</p><p>以防意外狀況發生，你也可以用一個硬盤的分區來代替U盤備份。</p>',13)),a("p",null,[o[1]||(o[1]=e("via: ",-1)),i(t,{href:"http://iloveubuntu.net/how-easily-backup-and-reuse-data-firefox-and-chromium"},{default:r(()=>[...o[0]||(o[0]=[e("http://iloveubuntu.net/how-easily-backup-and-reuse-data-firefox-and-chromium",-1)])]),_:1})]),a("p",null,[o[4]||(o[4]=e("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...o[2]||(o[2]=[e("LCTT",-1)])]),_:1}),o[5]||(o[5]=e(" 原創翻譯，",-1)),i(t,{href:"http://linux.cn/portal.php"},{default:r(()=>[...o[3]||(o[3]=[e("Linux中國",-1)])]),_:1}),o[6]||(o[6]=e(" 榮譽推出",-1))]),a("p",null,[o[8]||(o[8]=e("譯者: [Linchenguang][] 校對：",-1)),i(t,{href:"http://linux.cn/space/14763"},{default:r(()=>[...o[7]||(o[7]=[e("Caroline",-1)])]),_:1})]),a("p",null,[o[10]||(o[10]=e("Linchenguang ",-1)),i(t,{href:"mailto:1215412538@qq.com"},{default:r(()=>[...o[9]||(o[9]=[e("1215412538@qq.com",-1)])]),_:1})])])}const g=m(d,[["render",s]]);export{_ as __pageData,g as default};
